/**
 * ArvoBannerAlert -- vanilla JS implementation.
 *
 * Persistent inline alert banner with full parity to the React version at
 * packages/react/src/components/BannerAlert/BannerAlert.tsx. Six semantic
 * types (positive, info, neutral, warning, negative, block) drive border
 * color, background tint, title/icon color, and icon glyph. Two layout
 * modes: default (title + multi-line message + optional link) and compact
 * (message only, tighter padding). Optionally dismissible via a 16x16
 * `ArvoIconButton` close affordance (variant="tertiary", size="xs") wired
 * through the `arvo-bnr-alert__close` BEM class -- positioning is handled
 * by the SCSS, the chrome (background, border, focus, icon glyph) comes
 * from the icon-button system. The component does NOT auto-remove itself
 * on dismiss -- it fires `bnr-alert:dismiss` and calls onDismiss; the
 * consumer owns the lifecycle.
 *
 * See descriptors/banner-alert.json for the full spec.
 */

import { ArvoIconButton } from '../IconButton/IconButton';

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export type ArvoBannerAlertType =
  | 'positive'
  | 'info'
  | 'neutral'
  | 'warning'
  | 'negative'
  | 'block';

export type ArvoBannerAlertRole = 'status' | 'alert';

export interface ArvoBannerAlertOptions {
  /** Body message text. Required. */
  message: string;
  /** Semantic alert type. Defaults to "info". */
  type?: ArvoBannerAlertType;
  /** Optional title rendered above the message. Ignored in compact mode. */
  title?: string | null;
  /** Layout mode. When true, renders only the message with tighter padding. */
  isCompact?: boolean;
  /** Whether to render the close button on the right. Defaults to true. */
  isDismissible?: boolean;
  /** Optional link element rendered below the message in default mode. */
  link?: HTMLElement | null;
  /** Pattern A shimmer loading state. */
  isLoading?: boolean;
  /** Explicit ARIA role override. Defaults to type-derived role. */
  role?: ArvoBannerAlertRole;
  /** Fired when the close button is clicked or dismiss() is called. */
  onDismiss?: () => void;
}

// ---------------------------------------------------------------------------
// Constants / helpers
// ---------------------------------------------------------------------------

const TYPES: readonly ArvoBannerAlertType[] = [
  'positive',
  'info',
  'neutral',
  'warning',
  'negative',
  'block',
];

// Types that auto-resolve to role="alert" (assertive live region) when the
// caller does not pass an explicit role option.
const ASSERTIVE_TYPES: ReadonlySet<ArvoBannerAlertType> = new Set([
  'negative',
  'block',
]);

function resolveRole(
  type: ArvoBannerAlertType,
  roleOverride: ArvoBannerAlertRole | undefined,
): ArvoBannerAlertRole {
  if (roleOverride) return roleOverride;
  return ASSERTIVE_TYPES.has(type) ? 'alert' : 'status';
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export class ArvoBannerAlert {
  // -- DOM references -----------------------------------------------------
  private _root: HTMLElement | null;
  private _iconEl: HTMLSpanElement | null = null;
  private _contentEl: HTMLDivElement | null = null;
  private _copyEl: HTMLDivElement | null = null;
  private _titleEl: HTMLParagraphElement | null = null;
  private _msgEl: HTMLParagraphElement | null = null;
  private _linkEl: HTMLDivElement | null = null;
  private _closeEl: HTMLButtonElement | null = null;
  private _closeBtnInstance: ArvoIconButton | null = null;

  // -- Resolved state -----------------------------------------------------
  private _options: ArvoBannerAlertOptions;
  private _currentType: ArvoBannerAlertType;
  private _isCompact: boolean;
  private _isDismissible: boolean;
  private _isLoading: boolean;
  private _userRoleOverride: boolean;
  private _addedRole: boolean = false;
  private _addedAriaBusy: boolean = false;
  private _destroyed: boolean = false;

  static initialize(
    element: HTMLElement,
    options: ArvoBannerAlertOptions,
  ): ArvoBannerAlert {
    return new ArvoBannerAlert(element, options);
  }

  constructor(element: HTMLElement, options: ArvoBannerAlertOptions) {
    this._root = element;
    this._options = { ...options };

    const rawType = options?.type;
    this._currentType =
      rawType && (TYPES as readonly string[]).includes(rawType)
        ? rawType
        : 'info';
    this._isCompact = options?.isCompact === true;
    this._isDismissible = options?.isDismissible !== false; // default true
    this._isLoading = options?.isLoading === true;
    this._userRoleOverride = options?.role !== undefined;

    this._render();
  }

  // -- Render -------------------------------------------------------------

  private _render(): void {
    const root = this._root;
    if (!root) return;

    // Compose root classes (preserve any pre-existing classes the consumer
    // attached to the host element).
    root.classList.add('arvo-bnr-alert');
    root.classList.add(`arvo-bnr-alert--${this._currentType}`);
    if (this._isCompact) root.classList.add('arvo-bnr-alert--compact');
    if (this._isLoading) root.classList.add('loading');

    // Root role (always set; tracked for clean removal in destroy()).
    const resolvedRole = resolveRole(this._currentType, this._options.role);
    root.setAttribute('role', resolvedRole);
    this._addedRole = true;

    if (this._isLoading) {
      root.setAttribute('aria-busy', 'true');
      this._addedAriaBusy = true;
    }

    // -- Icon ------------------------------------------------------------
    const ico = document.createElement('span');
    ico.className = 'arvo-bnr-alert__ico o9con';
    ico.setAttribute('aria-hidden', 'true');
    this._iconEl = ico;
    root.appendChild(ico);

    // -- Content wrapper ------------------------------------------------
    const content = document.createElement('div');
    content.className = 'arvo-bnr-alert__content';
    this._contentEl = content;

    if (this._isCompact) {
      // Compact: __msg directly inside __content.
      const msg = document.createElement('p');
      msg.className = 'arvo-bnr-alert__msg';
      msg.textContent = this._options.message ?? '';
      this._msgEl = msg;
      content.appendChild(msg);
    } else {
      // Default: __copy (with optional __title + __msg) then optional __link.
      const copy = document.createElement('div');
      copy.className = 'arvo-bnr-alert__copy';
      this._copyEl = copy;

      if (this._options.title != null) {
        const titleEl = document.createElement('p');
        titleEl.className = 'arvo-bnr-alert__title';
        titleEl.textContent = this._options.title;
        this._titleEl = titleEl;
        copy.appendChild(titleEl);
      }

      const msg = document.createElement('p');
      msg.className = 'arvo-bnr-alert__msg';
      msg.textContent = this._options.message ?? '';
      this._msgEl = msg;
      copy.appendChild(msg);

      content.appendChild(copy);

      if (this._options.link != null) {
        const linkWrap = document.createElement('div');
        linkWrap.className = 'arvo-bnr-alert__link';
        linkWrap.appendChild(this._options.link);
        this._linkEl = linkWrap;
        content.appendChild(linkWrap);
      }
    }

    root.appendChild(content);

    // -- Close button ---------------------------------------------------
    // ArvoIconButton owns the chrome (variant="tertiary", size="xs") and
    // glyph; the SCSS rule on `.arvo-bnr-alert__close` only contributes
    // top-alignment + feedback-tonal hover overrides.
    if (this._isDismissible) {
      const closeBtn = document.createElement('button');
      closeBtn.className = 'arvo-bnr-alert__close';
      this._closeBtnInstance = ArvoIconButton.initialize(closeBtn, {
        variant: 'tertiary',
        size: 'xs',
        icon: 'close',
        tooltip: 'Dismiss alert',
        onClick: () => this.dismiss(),
      });
      // Belt-and-braces aria-label in case the consumer never enables
      // tooltips at runtime (the icon-button sets it from `tooltip` too).
      closeBtn.setAttribute('aria-label', 'Dismiss alert');

      this._closeEl = closeBtn;
      root.appendChild(closeBtn);
    }
  }

  // -- Public methods (dual-purpose getter/setter) ------------------------

  type(): ArvoBannerAlertType;
  type(newType: ArvoBannerAlertType): void;
  type(newType?: ArvoBannerAlertType): ArvoBannerAlertType | void {
    if (newType === undefined) return this._currentType;
    if (this._destroyed) return;
    if (!(TYPES as readonly string[]).includes(newType)) return;
    if (newType === this._currentType) return;

    const root = this._root;
    if (!root) return;

    root.classList.remove(`arvo-bnr-alert--${this._currentType}`);
    root.classList.add(`arvo-bnr-alert--${newType}`);
    this._currentType = newType;
    this._options.type = newType;

    // Re-resolve role only when the user did not explicitly pin it.
    if (!this._userRoleOverride) {
      const resolved = resolveRole(newType, undefined);
      root.setAttribute('role', resolved);
      this._addedRole = true;
    }
  }

  message(): string;
  message(text: string): void;
  message(text?: string): string | void {
    if (text === undefined) return this._options.message ?? '';
    if (this._destroyed) return;
    this._options.message = text;
    if (this._msgEl) {
      this._msgEl.textContent = text;
    }
  }

  title(): string | null;
  title(text: string | null): void;
  title(text?: string | null): string | null | void {
    if (arguments.length === 0) {
      return this._options.title ?? null;
    }
    if (this._destroyed) return;

    // Compact mode renders no __title slot -- silently ignore (mirrors React,
    // which simply does not render the title in compact mode).
    if (this._isCompact) {
      this._options.title = text ?? null;
      return;
    }

    const copy = this._copyEl;
    if (!copy) return;

    if (text == null) {
      // Remove existing title element (if any).
      if (this._titleEl) {
        this._titleEl.remove();
        this._titleEl = null;
      }
      this._options.title = null;
      return;
    }

    if (this._titleEl) {
      this._titleEl.textContent = text;
    } else {
      const titleEl = document.createElement('p');
      titleEl.className = 'arvo-bnr-alert__title';
      titleEl.textContent = text;
      this._titleEl = titleEl;
      // Title is the first child of __copy (above __msg).
      copy.insertBefore(titleEl, copy.firstChild);
    }
    this._options.title = text;
  }

  setLink(element: HTMLElement | null): void {
    if (this._destroyed) return;

    // Compact mode renders no __link slot -- mirrors React.
    if (this._isCompact) {
      this._options.link = element;
      return;
    }

    const content = this._contentEl;
    if (!content) return;

    if (element == null) {
      if (this._linkEl) {
        this._linkEl.remove();
        this._linkEl = null;
      }
      this._options.link = null;
      return;
    }

    if (this._linkEl) {
      // Replace existing single child with the new element (do NOT clone).
      while (this._linkEl.firstChild) {
        this._linkEl.removeChild(this._linkEl.firstChild);
      }
      this._linkEl.appendChild(element);
    } else {
      const linkWrap = document.createElement('div');
      linkWrap.className = 'arvo-bnr-alert__link';
      linkWrap.appendChild(element);
      this._linkEl = linkWrap;
      // __link is appended as the last child of __content (after __copy).
      content.appendChild(linkWrap);
    }
    this._options.link = element;
  }

  loading(): boolean;
  loading(state: boolean): void;
  loading(state?: boolean): boolean | void {
    if (state === undefined) return this._isLoading;
    if (this._destroyed) return;

    const root = this._root;
    if (!root) return;

    const next = state === true;
    if (next === this._isLoading) return;

    this._isLoading = next;
    this._options.isLoading = next;

    if (next) {
      root.classList.add('loading');
      root.setAttribute('aria-busy', 'true');
      this._addedAriaBusy = true;
    } else {
      root.classList.remove('loading');
      root.removeAttribute('aria-busy');
      this._addedAriaBusy = false;
    }
  }

  // -- dismiss / destroy --------------------------------------------------

  dismiss(): void {
    if (this._destroyed) return;
    const root = this._root;
    if (!root) return;

    root.dispatchEvent(
      new CustomEvent('bnr-alert:dismiss', {
        bubbles: false,
        cancelable: false,
      }),
    );

    this._options.onDismiss?.();
  }

  destroy(): void {
    if (this._destroyed) return;
    this._destroyed = true;

    const root = this._root;

    if (this._closeBtnInstance) {
      this._closeBtnInstance.destroy();
      this._closeBtnInstance = null;
    }

    if (root) {
      // Wipe inner DOM (host element survives; pre-existing host classes
      // outside our component namespace are preserved below).
      root.innerHTML = '';

      // Strip only classes we added (any "arvo-bnr-alert*" plus the state
      // class "loading"). Iterate over a snapshot since classList mutates.
      const toRemove: string[] = [];
      for (const cls of Array.from(root.classList)) {
        if (cls === 'loading' || cls.startsWith('arvo-bnr-alert')) {
          toRemove.push(cls);
        }
      }
      for (const cls of toRemove) {
        root.classList.remove(cls);
      }

      if (this._addedRole) {
        root.removeAttribute('role');
      }
      if (this._addedAriaBusy) {
        root.removeAttribute('aria-busy');
      }
    }

    this._root = null;
    this._iconEl = null;
    this._contentEl = null;
    this._copyEl = null;
    this._titleEl = null;
    this._msgEl = null;
    this._linkEl = null;
    this._closeEl = null;
  }
}
